import assert from 'node:assert/strict';
import test from 'node:test';

// Import the implementation under test from the repo workspace.
import { runWithLease } from '../acceptance/catcher-release.mjs';

function makePool() {
  let active = 0;
  return {
    acquire() {
      active += 1;
      return () => {
        active -= 1;
      };
    },
    get active() {
      return active;
    },
  };
}

test('OSMOGREP_REGRESSION: rejecting task releases lease and propagates error', async () => {
  const pool = makePool();
  const err = new Error('boom');

  await assert.rejects(
    () => runWithLease(pool, async () => {
      throw err;
    }),
    (e) => {
      // Must propagate the same error instance (not swallow/replace).
      assert.equal(e, err, 'OSMOGREP_REGRESSION: runWithLease did not propagate the same error');
      return true;
    },
  );

  assert.equal(
    pool.active,
    0,
    'OSMOGREP_REGRESSION: lease was not released after task rejection',
  );
});

